    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
try {
            // 1. Variáveis de Conexão (O GPS do Banco)
            String url = "jdbc:mysql://127.0.0.1:3306/jp_solucoes";
            String usuario = "root";
            String senha = "#Sabedoria2022"; // ALERTA: Substitua pela sua senha real!
            // 2. Estabelecendo a Ponte
            java.sql.Connection conexao = java.sql.DriverManager.getConnection(url, usuario, senha);
            // 3. O Algoritmo SQL de Injeção
            String sql = "INSERT INTO contratos (nome_cliente, bacen, rating, valor_contrato) VALUES (?, ?, ?, ?)";
            java.sql.PreparedStatement comando = conexao.prepareStatement(sql);

            // 4. Captura dos dados da tela
            comando.setString(1, jTextField1.getText()); 
            comando.setString(2, jTextField2.getText()); 
            comando.setString(3, jTextField3.getText()); 
            comando.setDouble(4, Double.parseDouble(jTextField4.getText())); 

            // 5. Disparo do Comando e Fechamento do Cofre
            comando.execute();
            conexao.close();

            // 6. Confirmação Visual para o Usuário
            javax.swing.JOptionPane.showMessageDialog(null, "Operação 3.1 Pro: Contrato gravado no Banco de Dados com sucesso!");

        } catch (Exception erro) {
            javax.swing.JOptionPane.showMessageDialog(null, "Falha na conexão com o Banco: " + erro.getMessage());
        }
    }//GEN-LAST:event_jButton1ActionPerformed

